    ["You became a thief?"] = "Ты стал вором?",
    ["使用后可在歌剧魅影玩法中表演<Highlight>魅影动作·月光滑步</>"] = "После использования вы можете выполнить <Highlight>Phantom Action: Moonwalk</> в игровом процессе Phantom of the Opera.",
    ["使用后获得<Highlight>铃兰与骑士背饰</>"] = "Используйте, чтобы получить <Highlight>Lily и аксессуар Knight Back </>.",
